"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8278],{64423:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"AmmoHudController","desc":"Drives the authored AmmoGui HUD (bottom-right). The ammo count is split\\nacross two labels either side of a divider, laid out horizontally:\\n\\n```\\nMainContainer (UIListLayout, Horizontal)\\n\u251c\u2500\u2500 AmmoCount         (TextLabel)  <-- loaded magazine / carried count\\n\u251c\u2500\u2500 Divider           (Frame)\\n\u2514\u2500\u2500 ReserveAmmoCount  (TextLabel)  <-- reserve pool\\n```\\n\\nFor a Gun that reads \\"mag | pool\\"; for a Throwable the carried count goes in\\n`AmmoCount` and `ReserveAmmoCount` shows an em-dash, so the widget keeps its\\nshape across weapon swaps. Hidden for Melee and when nothing relevant is\\nequipped. The GUI has no weapon-name label \u2014 the name is not displayed.\\n\\nThese instance names are load-bearing: renaming any of them in Studio breaks\\nthe controller at load. Reads through AmmoApi and reacts to weapon/ammo\\nSignals \u2014 it never talks to the server. AmmoController runs AmmoApi.Init();\\nthis only renders.","realm":["Client"],"source":{"line":26,"path":"src/StarterPlayer/StarterPlayerScripts/AmmoHudController.client.luau"}}')}}]);